// Assembles the candidate pool from "Read pool" and builds the Sonnet 5
// prompt: the same output this node produced when it made the reads itself.
const v = $('Validate focus').first().json;
const date = v.date;
const row_id = v.row_id;
const targets = v.targets;
const planned = $('Plan pool reads').all();
const got = {};
$input.all().forEach((res, i) => {
  const k = res.pairedItem && typeof res.pairedItem.item === 'number' ? res.pairedItem.item : i;
  const p = planned[k] && planned[k].json;
  if (!p) return;
  const r = res.json || {};
  got[p.key] = r.statusCode >= 200 && r.statusCode < 300 && Array.isArray(r.body) ? r.body : [];
});
const decisions = got.decisions || [];
const openTasks = got.openTasks || [];
const liveBets = got.liveBets || [];
const openLeads = got.openLeads || [];
const openVis = got.openVis || [];
const needyCustomers = got.needyCustomers || [];
const openIdeas = got.openIdeas || [];
const activeGuests = got.activeGuests || [];

function sample(rows, table) {
  return (rows || []).map(r => ({ table, id: r.id, ...r }));
}
const pool = [
  ...sample(decisions, 'decisions_waiting'),
  ...sample(openTasks, 'tasks'),
  ...sample(liveBets, 'bets'),
  ...sample(openLeads, 'leads'),
  ...sample(openVis, 'visibility_targets'),
  ...sample(needyCustomers, 'customers'),
  ...sample(openIdeas, 'content_ideas'),
  ...sample(activeGuests, 'guests'),
];

// Snapshot Marcus's nominated picks for audit.
const marcusSuggestions = targets
  .filter(t => t.source === 'marcus_nominated' && t.replaced_marcus_pick)
  .map((t, i) => ({
    rank: i + 1,
    title: (t.replaced_marcus_pick && t.replaced_marcus_pick.title) || t.text,
    concept_id: t.concept_id || null,
    meta: t.replaced_marcus_pick || {},
  }));

const system = [
  'You are the Focus Calibrator. Krish has locked 3 daily focus targets. Your job: for each row in the candidate pool, decide whether it materially advances ONE of the 3 targets and, if so, which one.',
  'Output strict JSON of shape: { "<table>:<id>": { "target": 1|2|3|null, "score": 0.0-1.0 } }. Only include keys for rows that score >= 0.5. A row gets target=null only when it could match multiple targets equally weakly, otherwise pick the strongest.',
  'Be conservative. A focus target is "reach $5K MRR by Friday" not "think about MRR". If a candidate row does not move the needle on any of the 3 targets, omit it entirely.',
  'No prose. No markdown fences. JSON only.',
].join('\n\n');

const user = JSON.stringify({
  date,
  targets: targets.map((t, i) => ({ n: i + 1, text: t.text, concept_id: t.concept_id })),
  candidate_pool: pool.slice(0, 200).map(r => ({
    key: `${r.table}:${r.id}`,
    title: r.title || r.full_name || r.idea || r.name || r.one_liner || r.hypothesis || (r.text || '').slice(0, 80),
    table: r.table,
    extras: {
      kind: r.kind, status: r.status, agent: r.agent,
      fit_score: r.fit_score, lever_score: r.lever_score,
      relevance_score: r.relevance_score, mrr_usd: r.mrr_usd,
      deadline_at: r.deadline_at, type: r.type,
    },
  })),
});

return [{ json: {
  date, row_id, targets, marcus_suggestions: marcusSuggestions,
  pool_size: pool.length,
  anthropic_body: {
    model: 'claude-sonnet-5',
    thinking: { type: 'disabled' },
    max_tokens: 2500,
    system,
    messages: [{ role: 'user', content: user }],
  },
} }];

// Phase 1 of focus + tasks inbox brief: Focus Calibrator.
// Validates the inbound calibration request. The candidate pool is read by
// "Read pool" over the stored Supabase credential and assembled into the
// Sonnet 5 prompt by "Validate + fetch pool". This node used to make those
// reads itself with the service-role key written into its source (moved
// 2026-10-03).
const input = $input.first().json;
const body = input.body || input;
const date = body.date;
const row_id = body.row_id;
const targets = Array.isArray(body.targets) ? body.targets : [];

if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date))
  throw new Error('date must be YYYY-MM-DD');
if (targets.length !== 3)
  throw new Error('targets must be exactly 3');
for (const t of targets) {
  if (!t || typeof t.text !== 'string' || !t.text.trim())
    throw new Error('every target must have non-empty text');
}

// A missing concept_id used to go to compute_concept_slug with p_text. The
// function's argument is p_name, so that call failed on every run and the id
// was always left null. It is set to null here directly, as it always ended up.
for (const t of targets) {
  if (!t.concept_id) t.concept_id = null;
}

return [{ json: { date, row_id, targets } }];

// The eight candidate-pool reads, one item each, for "Read pool". A read that
// fails counts as no rows, as before. The bets read asks for bets.title, which
// the table does not have, so it has always come back empty; kept as it was.
const nowIso = new Date().toISOString();
const thirtyDaysFromNow = new Date(Date.now() + 30 * 86400000).toISOString();
const reads = [
  ['decisions', `decisions_waiting?select=*&order=sort_at.asc&limit=80`],
  ['openTasks', `tasks?status=in.(waiting,active,in_progress,blocked)&select=id,title,agent,status,lever_score,priority,due_date&limit=40`],
  ['liveBets', `bets?status=eq.live&select=id,title,hypothesis,est_mrr_impact_usd,time_box_days&limit=20`],
  ['openLeads', `leads?status=in.(ready,contacted,conversation)&select=id,full_name,company,status,fit_score,tier,why_relevant&limit=30`],
  ['openVis', `visibility_targets?status=in.(queued,applied,accepted)&deadline_at=gt.${nowIso}&select=id,title,type,deadline_at,relevance_score&limit=30`],
  ['needyCustomers', `customers?kind=eq.paid&churned_at=is.null&needs_outreach_at=not.is.null&needs_outreach_at=lte.${thirtyDaysFromNow}&select=id,full_name,product,mrr_usd,needs_outreach_at&limit=20`],
  ['openIdeas', `content_ideas?state=in.(seeded,researching,drafting,review,approved)&select=id,idea,thesis,state,pillar_id&order=updated_at.desc&limit=30`],
  ['activeGuests', `guests?status=in.(scouted,enriched,pitched,responded,scheduled,confirmed)&select=id,name,one_liner,status,podcast_target&order=updated_at.desc&limit=30`],
];
return reads.map(([key, path]) => ({ json: { key, path } }));

// Parses Sonnet's match and builds the two writes. "Persist focus" and "Log
// calibration run" send them over the stored Supabase credential, and "Parse +
// persist" returns what this step always returned. The writes used to be made
// here with the service-role key written into the source (moved 2026-10-03).
const carry = $('Validate + fetch pool').first().json;
const raw = $input.first().json;
const blocks = raw.content || [];
const text = blocks.map(b => b.text || '').join('').trim();

let relevance_index = {};
try {
  const a = text.indexOf('{'); const b = text.lastIndexOf('}');
  if (a >= 0 && b > a) relevance_index = JSON.parse(text.slice(a, b + 1));
} catch { relevance_index = {}; }

// Defensive cleanup of any non-conformant keys.
const clean = {};
for (const [k, v] of Object.entries(relevance_index || {})) {
  if (!v || typeof v !== 'object') continue;
  const t = (v.target === 1 || v.target === 2 || v.target === 3) ? v.target : null;
  const s = typeof v.score === 'number' ? Math.max(0, Math.min(1, v.score)) : 0;
  if (s < 0.5) continue;
  clean[String(k)] = { target: t, score: s };
}

// Persist concept_ids + relevance_index + marcus_suggestions + status.
const patch = {
  target_1_concept_id: carry.targets[0].concept_id || null,
  target_2_concept_id: carry.targets[1].concept_id || null,
  target_3_concept_id: carry.targets[2].concept_id || null,
  relevance_index: clean,
  marcus_suggestions: carry.marcus_suggestions || [],
  status: 'calibrated',
  calibrated_at: new Date().toISOString(),
};
// Workflow_runs heartbeat for self-healing observability. It carries no
// workflow_id or agent_id, which the table requires, so the insert has never
// landed; kept as it was, and it still cannot fail the run.
const run = {
  workflow_name: 'Krish | Mindmaker OS | Focus Calibrator',
  outcome: 'ok',
  status: 'success',
  started_at: new Date().toISOString(),
  finished_at: new Date().toISOString(),
  metadata: { focus_date: carry.date, pool_size: carry.pool_size, matched: Object.keys(clean).length },
};

// Lane sizes for the Telegram notice.
const lanes = { 1: 0, 2: 0, 3: 0, muted: 0 };
for (const v of Object.values(clean)) {
  if (v.target === 1 || v.target === 2 || v.target === 3) lanes[v.target] += 1;
  else lanes.muted += 1;
}
const telegram_text = `Focus locked for ${carry.date}. Lane 1: ${lanes[1]}, Lane 2: ${lanes[2]}, Lane 3: ${lanes[3]}, muted/unscoped: ${lanes.muted}.`;

return [{ json: { date: carry.date, patch, run, result: { ok: true, date: carry.date, lanes, matched: Object.keys(clean).length, telegram_text } } }];
